inputs.common/scripted_buttons/07_japan_buttons:
button_je_tenpo_combat_rice_hoarding = {
	name = button_je_tenpo_combat_rice_hoarding
	desc = button_je_tenpo_combat_rice_hoarding_desc

	visible = {
		NOT = {
			has_variable = button_je_tenpo_combat_rice_hoarding_var
		}
	}

	possible = {
		OR = {
			AND = {
	            country_has_building_type_levels = {
	                target = bt:building_rice_farm
	                value >= 40
	            }
	            NOT = {
	            	any_scope_state = {
	            		state_region = {
	            			is_homeland = cu:japanese
	            		}
	            		has_famine = yes
	            	}
	            }
	        }
			market_capital.market = {
				mg:grain = {
					market_goods_pricier < 0.1
				}
			}
		}
	}

	selected = {

	}

	effect = {
		set_variable = button_je_tenpo_combat_rice_hoarding_var
		je:je_tenpo_crisis = {
			remove_modifier = modifier_rice_hoarding
		}
	}

	ai_chance = {
		value = 100 # Should be used as soon as it's available
	}
}

button_je_tenpo_frugal_ordinance = {
	name = button_je_tenpo_frugal_ordinance
	desc = button_je_tenpo_frugal_ordinance_desc

	visible = {
		NOT = {
			has_variable = button_je_tenpo_frugal_ordinance_var
		}
	}

	possible = {
		OR = {
			has_law = law_type:law_intermediate_edo_system
			has_law = law_type:law_strict_edo_system
		}
		legitimacy >= 75
		ig:ig_petty_bourgeoisie = {
			is_in_government = no
		}
	}

	effect = {
		set_variable = button_je_tenpo_frugal_ordinance_var
		add_loyalists = {
			strata = upper
			value = medium_radicals
		}
		add_radicals = {
			strata = lower
			value = medium_radicals
		}
		active_law:lawgroup_edo_social_system ?= {
			add_amendment = {
				type = amendment_frugal_ordinance
				sponsor = PREV.ig:ig_armed_forces
				cooldown = 240
			}
		}
	}

	ai_chance = {
		value = 10
	}
}

button_je_tenpo_confiscate_land = {
	name = button_je_tenpo_confiscate_land
	desc = button_je_tenpo_confiscate_land_desc

	visible = {
		NOT = {
			has_variable = button_je_tenpo_confiscate_land_var
		}
	}

	possible = {
		OR = {
			custom_tooltip = {
				text = ruler_is_imperious_tt
				ruler ?= {
					has_trait = imperious
				}
			}
			custom_tooltip = {
				text = ruler_is_modernizer_or_mitogaku_tt
				ruler ?= {
					OR = {
						has_ideology = ideology:ideology_mitogaku
						has_ideology = ideology:ideology_modernizer_leader
					}
				}
			}
			custom_tooltip = {
				text = opium_war_has_happened_tt
				has_variable = opium_war_has_happened_jap_var
			}
		}
		s:STATE_KANTO = {
			any_scope_state = {
				owner = root
				has_building = building_naval_fortification
			}
		}
		s:STATE_KANSAI = {
			any_scope_state = {
				owner = root
				has_building = building_naval_fortification
			}
		}
	}

	selected = {
	}

	effect = {
		set_variable = button_je_tenpo_confiscate_land_var
		trigger_event = {
			id = tenpo_events.5
			popup = yes	
		}
		add_modifier = {
			name = modifier_consolidation_payments
			days = normal_modifier_time
			multiplier = money_amount_multiplier_medium
		}
		s:STATE_KANTO = {
			random_scope_state = {
				limit = {
					owner = root
				}
				add_radicals_in_state = {
					value = small_radicals
				}
				add_modifier = {
					name = modifier_consolidated_state_land
					days = very_long_modifier_time
				}
			}
		}
		s:STATE_KANSAI = {
			random_scope_state = {
				limit = {
					owner = root
				}
				add_radicals_in_state = {
					value = small_radicals
				}
				add_modifier = {
					name = modifier_consolidated_state_land
					days = very_long_modifier_time
				}
			}
