		flags = { hidden invalid_outcome }
		conclusion_desc = je_standard_failure_conclusion_desc
		trigger = {
			has_variable = cancel_sa_migration_var
		}
		effect = {
			je_south_america_migration_cleanup = yes
		}
	}

