	on_weekly_pulse = {
		effect = {
			scope:journal_entry = {
				if = {
					limit = {
						is_progressing = yes
					}
					change_variable = {
						name = num_weeks_in_progress
						add = 1
					}
				}
			}
		}
	}

	outcome = {
		header = je_standard_completion_header
		effect_header = je_standard_on_completion_header
		color = "gold_positive"
		conclusion_desc = je_standard_completion_conclusion_desc
		trigger = {
			scope:journal_entry = { is_goal_complete = yes }
		}
		effect = {
			owner = {
				start_tutorial_lesson = {
					tutorial_lesson = lesson_fix_capacity_deficit_complete
					journal_entry = je:je_tutorial_capacity_deficit
				}
			}
		}
	}

	current_value = {
		value = scope:journal_entry.var:num_weeks_in_progress
	}

	goal_add_value = {
		value = 4
	}

	is_progressing = {
		trigger_if = {
			limit = {
				has_variable = tut_bureaucracy_deficit
			}
			bureaucracy > 0
		}
		trigger_else_if = {
			limit = {
				has_variable = tut_authority_deficit
			}
			authority > 0
		}
		trigger_else_if = {
			limit = {
				has_variable = tut_influence_deficit
			}
			influence > 0
		}
	}

	immediate = {
		scope:journal_entry = {
			set_variable = {
				name = num_weeks_in_progress
				value = 0
			}
		}
		if = {
			limit = {
				bureaucracy < -10
			}
			set_variable = tut_bureaucracy_deficit
		}
		else_if = {
			limit = {
				authority < -10
			}
			set_variable = tut_authority_deficit
		}
		else_if = {
			limit = {
				influence < -10
			}
			set_variable = tut_influence_deficit
		}
	}

	status_desc = {
		first_valid = {
			triggered_desc = {
				desc = je_tutorial_capacity_deficit_status_bureaucracy
				trigger = {
					has_variable = tut_bureaucracy_deficit
				}
			}
			triggered_desc = {
				desc = je_tutorial_capacity_deficit_status_authority
				trigger = {
					has_variable = tut_authority_deficit
				}
			}
			triggered_desc = {
				desc = je_tutorial_capacity_deficit_status_influence
				trigger = {
					has_variable = tut_influence_deficit
				}
			}
		}
	}

	weight = 1056
	transferable = yes
	should_update_on_player_command = yes

	should_be_pinned_by_default_uninvolved_or_context = yes
}

